process.on('SIGTERM', async () => {   // 15 — 정중한 종료 요청
  server.close();                    // 새 요청 그만 받기
  await db.end();                    // 연결·자원 정리
  process.exit(0);                   // 깨끗이 종료
});
// SIGKILL(9)은 잡을 수 없다 — 정리 코드가 안 돈다.
// 그래서 오케스트레이터는 먼저 SIGTERM 을 주고(정리 시간),
// 유예 후에도 안 죽으면 SIGKILL 을 보낸다.
